list_shipping_profiles.code:
var response = await client.ShippingProfiles.ListShippingProfilesAsync(
    new Dictionary<string, object?> { ["search"] = "metro", ["sort"] = "name", ["order"] = "asc", ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var profile in ((IReadOnlyList<object?>)body["shipping_profiles"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{profile["id"]} {profile["name"]} {profile["rule_preference"]} {profile["default"]} {profile["rules_count"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

